'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Project } from '../../types';
import GameProjectConsole from './GameProjectConsole';
import GameIdentityCore from './GameIdentityCore';
import GameCommsRelay from './GameCommsRelay';
import GameContactTerminal from './GameContactTerminal';
import GameBlogConsole from './GameBlogConsole';
import CRTOverlay from './ui/CRTOverlay';
import { renderGame } from './gameRenderer';

import GameA11yOverlay from './GameA11yOverlay';
import StoryHUD from './StoryHUD';
import { IconArrow } from '../ui/Icons';
import { useGamePhysics, GamePhysicsState, GameObject } from '../../hooks/useGamePhysics';
import { useGameInput } from '../../hooks/useGameInput';
import { CONTACT_EMAIL } from '../../constants';
import { useStoryModals } from '../../hooks/useStoryModals';

interface StoryModeProps {
    active: boolean;
    onExit: () => void;
    onSelectProject: (project: Project) => void;
}

type GameView = 'world' | 'project' | 'identity' | 'comms';

// --- ARCHITECTURAL NOTE ---
// This component acts as the "Game Kernel". It orchestrates:
// 1. Rendering (via gameRenderer.ts)
// 2. Physics & Collisions (via useGamePhysics hook)
// 3. Input Handling (via useGameInput hook)
// 4. State Management (via useStoryModals hook)
//
// We explicitly DECOUPLED the HUD and specific Modals to keep this file focused
// on the "Game Loop" and coordination logic. This is the "Controller" in MVC.
// --------------------------

const StoryMode: React.FC<StoryModeProps> = ({ active, onExit, onSelectProject }) => {
    // View State
    const [currentView, setCurrentView] = useState<GameView>('world');

    // Modals State
    const modals = useStoryModals();
    const {
        projectModal, identityModal, contactModal, blogModal, modalOriginRect
    } = modals.state;
    const {
        setProjectModal, setIdentityModal, setContactModal, setBlogModal, setModalOriginRect, closeAll
    } = modals.actions;

    // Gameplay State
    const [visitedNodes, setVisitedNodes] = useState<Set<string>>(new Set());

    // --- Interaction Callback ---
    const onInteract = useCallback((target: GameObject) => {
        setVisitedNodes(prev => new Set(prev).add(target.id));

        if (target.type === 'project' && target.data) {
            setProjectModal(target.data);
        } else if (target.id === 'contact') {
            setContactModal(true);
        } else if (target.id === 'about') {
            setIdentityModal(true);
        } else if (target.id === 'blog') {
            setBlogModal(true);
        }
    }, [setProjectModal, setContactModal, setIdentityModal, setBlogModal]);

    // --- Input & Physics Ref Sync ---
    const latestInteractionTarget = React.useRef<GameObject | null>(null);

    // --- Input Handlers ---
    const handleEscape = useCallback(() => {
        // Priority 1: Close Modals
        if (modals.isAnyOpen) {
            closeAll();
            return;
        }

        // Priority 2: Exit Game
        onExit();
    }, [modals.isAnyOpen, closeAll, onExit]);

    const handleInputInteract = useCallback(() => {
        if (latestInteractionTarget.current) {
            onInteract(latestInteractionTarget.current);
        }
    }, [onInteract]);

    // --- Input Hook ---
    const inputKeys = useGameInput({
        active,
        onEscape: handleEscape,
        onInteract: handleInputInteract
    });

    // --- Physics Hook ---

    // Extracted Renderer
    const draw = useCallback((ctx: CanvasRenderingContext2D, state: GamePhysicsState) => {
        renderGame(ctx, state, visitedNodes);
    }, [visitedNodes]);

    // Use the Hook
    const physics = useGamePhysics({
        active,
        onInteract,
        onDraw: draw,
        onExit, // Legacy exit handler (passed for completeness)
        currentView,
        keys: inputKeys
    });

    // Sync Ref for Input Handler
    useEffect(() => {
        latestInteractionTarget.current = physics.interactionTarget;
    }, [physics.interactionTarget]);

    // We must handle setting modalOriginRect when interaction occurs.
    useEffect(() => {
        if (physics.interactionTarget && (physics.interactionTarget.type === 'project' || physics.interactionTarget.id === 'contact' || physics.interactionTarget.id === 'about')) {
            // But this effect runs whenever interactionTarget changes, which happens every frame during proximity.
            // We only want to set bounds when we *actually enter* the modal (triggered by onInteract).
            // So we do it in onInteract?
            // Yes, but we need camera pos.
            // onInteract is above. We need 'physics' variable to access cameraRef.
            // But 'physics' is defined *after* 'onInteract' because 'onInteract' is passed TO 'useGamePhysics'.
            // CIRCULAR DEPENDENCY.

            // Fix: Use a ref for camera that we pass TO the hook? Or let the hook return it and we use it in a separate effect?
            // The hook *returns* cameraRef.
            // But onInteract is a callback passed *to* the hook.
            // So inside onInteract, we can't see the 'physics' object constant yet.

            // Yes. When `projectModal` becomes non-null, capture current camera pos.
        }
    }, [physics]); // Added physics as dependency

    // Unified Escape Key Handler & Interaction
    // --- Manual Escape Logic Removed (Handled by useGameInput) ---

    // Effect to Capture Bounds on Modal Open
    useEffect(() => {
        if (projectModal || identityModal || contactModal || blogModal) {
            const cam = physics.cameraRef.current;
            const cvs = physics.canvasRef.current;
            // We need the target object.
            // It's likely `physics.interactionTarget`.
            const target = physics.interactionTarget;

            if (cam && cvs && target) {
                const cx = cvs.width / 2;
                const cy = cvs.height / 2;
                setModalOriginRect({
                    x: target.x - cam.x + cx,
                    y: target.y - cam.y + cy,
                    w: target.w,
                    h: target.h
                });
            }
        }
    }, [projectModal, identityModal, contactModal, blogModal, physics.cameraRef, physics.canvasRef, physics.interactionTarget]);

    // Portal Logic: Ensure we are on client and have body access
    const [mounted, setMounted] = useState(false);
    useEffect(() => {
        setMounted(true);
        return () => setMounted(false);
    }, []);

    if (!active || !mounted) return null;

    // Use Portal to escape 'app/template.tsx' transforms
    const content = (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className={`fixed inset-0 z-[9999] bg-black text-white font-mono overflow-hidden touch-none ${physics.isHoveringObject ? 'cursor-pointer' : 'cursor-crosshair'}`}
        >
            <canvas
                ref={physics.canvasRef}
                className="block w-full h-full"
                {...physics.canvasHandlers}
            />

            {/* Accessibility Overlay */}
            <GameA11yOverlay
                active={active}
                objects={physics.objects.current}
                onInteract={onInteract}
            />

            {/* HUD */}
            {!projectModal && !identityModal && !contactModal && (
                <StoryHUD
                    onExit={onExit}
                    interactionTarget={physics.interactionTarget || null}
                    onInteract={onInteract}
                    onMobileInput={physics.handleMobileInput}
                />
            )}

            {/* Modals */}
            <AnimatePresence>
                {projectModal && (
                    <GameProjectConsole
                        project={projectModal}
                        onBack={() => setProjectModal(null)}
                        initialBounds={modalOriginRect}
                    />
                )}
                {identityModal && (
                    <GameIdentityCore
                        onBack={() => setIdentityModal(false)}
                        initialBounds={modalOriginRect}
                    />
                )}
                {contactModal && (
                    <GameContactTerminal
                        onBack={() => setContactModal(false)}
                        initialBounds={modalOriginRect}
                    />
                )}
                {blogModal && (
                    <GameBlogConsole
                        onBack={() => setBlogModal(false)}
                    />
                )}
            </AnimatePresence>

            {/* CRT Overlay */}
            <div className="absolute inset-0 z-10 pointer-events-none">
                <CRTOverlay />
            </div>
        </motion.div>
    );

    // Dynamic Import or Direct Usage? Direct is fine for ReactDOM
    const { createPortal } = require('react-dom');
    return createPortal(content, document.body);
};

export default StoryMode;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Project } from '../../types';
import { IconArrow, IconBrain, IconGlobe, IconGov, IconUsers, IconChart, IconTrophy } from '../ui/Icons';

interface ProjectCardProps {
  project: Project;
  onClick: (project: Project) => void;
  className?: string;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ project, onClick, className }) => {
  const [tilt, setTilt] = useState({ rotateX: 0, rotateY: 0 });

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = (e.clientX - rect.left - rect.width / 2) / 25;
    const y = (e.clientY - rect.top - rect.height / 2) / 25;
    setTilt({ rotateX: -y, rotateY: x });
  };

  const handleMouseLeave = () => {
    setTilt({ rotateX: 0, rotateY: 0 });
  };

  const getIcon = (id: string) => {
    switch (id) {
      case 'nova': return <IconBrain className="w-32 h-32 text-pop relative z-10 opacity-80 pixel-icon" />;
      case 'wfp': return <IconGlobe className="w-6 h-6 opacity-50 pixel-icon" />;
      case 'city': return <IconGov className="w-24 h-24 opacity-20 self-end mt-4 pixel-icon" />;
      case 'pasa': return <IconUsers className="w-6 h-6 text-pop pixel-icon" />;
      case 'ess': return <IconUsers className="w-6 h-6 opacity-50 pixel-icon" />;
      case 'weg': return <IconGlobe className="w-24 h-24 text-pop opacity-20 pixel-icon" />;
      case 'sctc': return <IconChart className="w-24 h-24 text-ink/10 dark:text-white/10 pixel-icon" />;
      default: return null;
    }
  };

  // Special layouts based on card type to match visual parity
  if (project.id === 'nova') {
    return (
      <motion.div
        onClick={() => onClick(project)}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        style={{ rotateX: tilt.rotateX, rotateY: tilt.rotateY, transformStyle: 'preserve-3d' }}
        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
        className={`project-card ${className} border border-ink dark:border-white/20 p-8 group hover:shadow-hard transform transition-shadow active:scale-[0.98] bg-cream dark:bg-black cursor-hoverable cursor-pointer`}
      >
        <div className="h-full flex flex-col md:flex-row pointer-events-none">
          <div className="flex-1 flex flex-col justify-between">
            <div>
              <div className="flex justify-between items-center mb-4">
                <span className="font-mono text-xs bg-ink text-cream dark:bg-white dark:text-ink px-2 py-1">{project.tag.toUpperCase()}</span>
                <div className="flex items-center gap-2">
                  <span className="font-mono text-xs text-pop font-bold animate-pulse">● LIVE</span>
                  <IconArrow className="w-6 h-6 text-pop group-hover:translate-x-1 transition-transform pixel-icon" />
                </div>
              </div>
              <h3 className="font-display font-bold text-3xl mb-2">{project.title}</h3>
              <p className="text-sm font-mono text-pop mb-4">{project.subtitle}</p>
              <p className="opacity-70 max-w-md">{project.context}</p>
            </div>
            <div className="mt-8">
              <span className="bg-gold text-ink text-xs font-bold px-3 py-1 inline-flex items-center gap-2 mb-2 shadow-sm w-fit uppercase tracking-wider">
                <IconTrophy className="w-4 h-4 pixel-icon" /> <span className="text-pop font-black">$20K</span> BEST BUSINESS VALUE PRIZE
              </span>
              <div className="flex gap-2">
                {project.stack.slice(0, 3).map(s => (
                  <span key={s} className="border border-current opacity-30 px-2 py-1 text-xs font-mono">{s}</span>
                ))}
              </div>
            </div>
          </div>
          <div className="w-full md:w-1/3 bg-ink dark:bg-zinc-800 flex items-center justify-center relative overflow-hidden p-8 md:p-0">
            <div className="absolute inset-0 opacity-20" style={{ backgroundImage: 'radial-gradient(#FF4400 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>
            {getIcon('nova')}
          </div>
        </div>
      </motion.div>
    );
  }

  // WEG Prominent layout
  if (project.id === 'weg') {
    return (
      <motion.div
        onClick={() => onClick(project)}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        style={{ rotateX: tilt.rotateX, rotateY: tilt.rotateY, transformStyle: 'preserve-3d' }}
        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
        className={`project-card ${className} border border-ink dark:border-white/20 p-8 group hover:shadow-hard transform transition-shadow active:scale-[0.98] cursor-hoverable cursor-pointer bg-white dark:bg-charcoal flex flex-col justify-between overflow-hidden`}
      >
        <div className="flex flex-col md:flex-row gap-8 h-full pointer-events-none">
          <div className="flex-1 flex flex-col justify-between min-w-0">
            <div>
              <div className="flex justify-between items-center mb-4">
                <span className="font-mono text-xs bg-ink text-cream dark:bg-white dark:text-ink px-2 py-1">ENTREPRENEURSHIP</span>
              </div>
              <h3 className="font-display font-bold text-3xl mb-2 break-words">{project.title}</h3>
              <p className="text-sm font-mono opacity-50 mb-4">{project.subtitle}</p>
              <p className="opacity-70 max-w-lg">{project.context}</p>
            </div>
            <div className="mt-6 flex gap-2 flex-wrap">
              {project.stack.map(s => (
                <span key={s} className="border border-current opacity-30 px-2 py-1 text-xs font-mono">{s}</span>
              ))}
            </div>
          </div>
          <div className="md:w-1/3 flex-shrink-0 flex items-center justify-center bg-cream dark:bg-zinc-800/50 p-4 border border-ink/5 dark:border-white/5 overflow-hidden">
            {project.image ? (
              <img src={project.image} alt={project.title} className="w-full h-full object-cover opacity-90 hover:scale-105 transition-transform duration-500" />
            ) : (
              getIcon('weg')
            )}
          </div>
        </div>
      </motion.div>
    );
  }

  // Fallback generic card structure customized per item to match HTML structure
  return (
    <div onClick={() => onClick(project)} className={`project-card ${className} border border-ink dark:border-white/20 p-6 group hover:shadow-hard transform transition-all active:scale-[0.98] cursor-hoverable cursor-pointer flex flex-col justify-between ${project.id === 'city' ? 'bg-pop text-white' : 'bg-white dark:bg-charcoal'}`}>
      <div className={`h-full flex flex-col ${project.id === 'sctc' ? 'md:flex-row gap-6' : 'justify-between'} pointer-events-none`}>
        <div className={project.id === 'sctc' ? 'flex-1' : ''}>
          {project.id === 'wfp' && <div className="flex justify-between items-center mb-4"><span className="font-mono text-xs border border-current px-2 py-1 opacity-60">RESEARCH</span></div>}
          {project.id === 'city' && <span className="font-mono text-xs bg-white text-pop px-2 py-1 inline-block mb-4">STRATEGY</span>}
          {project.id === 'pasa' && <div className="flex justify-between items-start mb-4"><h3 className="font-display font-bold text-2xl">{project.title}</h3>{getIcon('pasa')}</div>}
          {project.id === 'ess' && <div className="flex justify-between items-start mb-4"><h3 className="font-display font-bold text-2xl leading-tight">{project.title}</h3>{getIcon('ess')}</div>}

          {project.id === 'sctc' && <span className="font-mono text-xs bg-ink text-cream dark:bg-white dark:text-ink px-2 py-1 mb-4 inline-block">DATA ANALYSIS</span>}

          {(project.id !== 'pasa' && project.id !== 'ess') && <h3 className="font-display font-bold text-2xl mb-1">{project.title}</h3>}

          {project.id === 'pasa' && <p className="text-sm font-mono text-pop mt-1">LEADERSHIP</p>}
          {project.id === 'ess' && <p className="text-sm font-mono opacity-50 mt-1">CO-FOUNDER</p>}

          {(project.id !== 'pasa' && project.id !== 'ess') && <p className="text-sm font-mono opacity-50 mb-4">{project.subtitle}</p>}

          <p className="text-sm opacity-70">
            {project.context}
          </p>
        </div>

        {project.id === 'wfp' && (
          <div className="mt-6 pt-4 border-t border-dashed border-current opacity-30 flex justify-end">
            {/* Cleaner visual without code snippet */}
            {project.image ? (
              <img src={project.image} alt={project.title} className="w-12 h-12 object-cover rounded-sm border border-current opacity-80" />
            ) : (
              getIcon('wfp')
            )}
          </div>
        )}
        {project.id === 'sctc' && <div className="flex items-end">{getIcon('sctc')}</div>}
      </div>
    </div>
  );
};

export default ProjectCard;
